UPDATE wiki_type_categories SET rollup = '{"mode":"directory","levels":["university"],"enabled":true,"metrics":[]}'::jsonb WHERE space_type_id = '00000000-0000-0000-0000-000000000060' AND slug = 'universities';
UPDATE wiki_type_categories SET rollup = NULL WHERE space_type_id = '00000000-0000-0000-0000-000000000060' AND slug = 'visa-routes';
UPDATE wiki_type_categories SET rollup = NULL WHERE space_type_id = '00000000-0000-0000-0000-000000000061' AND slug = 'banking';
UPDATE wiki_type_categories SET rollup = '{"mode":"directory","levels":["university"],"enabled":true,"metrics":[]}'::jsonb WHERE space_type_id = '00000000-0000-0000-0000-000000000061' AND slug = 'universities';

-- 2. Drop page templates introduced here.
DELETE FROM wiki_type_page_templates t
USING wiki_type_categories c
JOIN (VALUES ('00000000-0000-0000-0000-000000000062','cost-of-living','clothing-shoes'),('00000000-0000-0000-0000-000000000062','cost-of-living','salaries-financing'),('00000000-0000-0000-0000-000000000066','tuition-fees','program-fees'),('00000000-0000-0000-0000-000000000071','plan-your-visit','tickets')) AS v(tid, cslug, tslug)
